/* 
   Leap Studio - Styles 
   OKLCH is used for colors per brand guidelines. 
*/

:root {
  /* Colors */
  --bg-color: oklch(12% 0.01 250); /* Near Black */
  --surface-color: oklch(20% 0.01 250); /* Dark Gray */
  --surface-hover: oklch(25% 0.01 250);
  --text-primary: oklch(98% 0 0); /* White */
  --text-secondary: oklch(75% 0 0); /* Neutral Gray */
  --accent-primary: oklch(65% 0.2 250); /* Electric Blue */
  --accent-secondary: oklch(75% 0.18 45); /* Warm Amber */
  --border-color: oklch(30% 0 0);
  --error: oklch(60% 0.2 20);

  /* Typography */
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;

  /* Layout */
  --max-width: 1280px;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 2rem;
  --spacing-lg: 4rem;
  --spacing-xl: 8rem;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 16px;
  --radius-full: 999px;

  /* Transitions */
  --transition-fast: 0.2s ease;
  --transition-normal: 0.3s ease;
  --transition-slow: 0.5s cubic-bezier(0.25, 1, 0.5, 1);
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-color);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover {
  color: var(--accent-primary);
}

img {
  max-width: 100%;
  display: block;
}

ul {
  list-style: none;
}

button {
  background: none;
  border: none;
  cursor: pointer;
  font-family: inherit;
  color: inherit;
}

/* Layout Classes */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

.container-fluid {
  width: 100%;
  padding: 0 var(--spacing-md);
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

h1 { font-size: clamp(2.5rem, 5vw, 4.5rem); }
h2 { font-size: clamp(2rem, 4vw, 3.5rem); margin-bottom: var(--spacing-md); }
h3 { font-size: clamp(1.25rem, 2vw, 1.75rem); margin-bottom: var(--spacing-xs); }
h4 { font-size: 1.1rem; font-weight: 500; }

p {
  color: var(--text-secondary);
  font-size: 1.125rem;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.875rem 1.5rem;
  border-radius: var(--radius-full);
  font-weight: 500;
  font-size: 1rem;
  transition: all var(--transition-fast);
  text-align: center;
}

.btn-primary {
  background-color: var(--text-primary);
  color: var(--bg-color);
}

.btn-primary:hover {
  background-color: var(--accent-primary);
  color: var(--text-primary);
}

.btn-outline {
  border: 1px solid var(--text-primary);
  color: var(--text-primary);
}

.btn-outline:hover {
  background-color: var(--text-primary);
  color: var(--bg-color);
}

/* Header & Navigation */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  z-index: 1000;
  background: rgba(12, 12, 14, 0.8);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
  transition: transform var(--transition-normal);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 5rem;
}

.logo {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text-primary);
}

.logo:hover { color: var(--text-primary); }

.main-nav {
  display: flex;
  align-items: center;
}

.nav-list {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.nav-list a, .language-toggle {
  font-size: 0.875rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-secondary);
}

.nav-list a:hover, .language-toggle:hover {
  color: var(--text-primary);
}

.language-dropdown-wrapper {
  position: relative;
}

.language-dropdown {
  position: absolute;
  top: 100%;
  right: 0;
  margin-top: 0.5rem;
  background-color: var(--surface-color);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 0.5rem 0;
  min-width: 120px;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-10px);
  transition: all var(--transition-fast);
}

.language-dropdown.show {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.language-dropdown li a {
  display: block;
  padding: 0.5rem 1rem;
  color: var(--text-primary);
  text-transform: none;
  letter-spacing: 0;
}

.language-dropdown li a:hover {
  background-color: var(--surface-hover);
}

.mobile-toggle {
  display: none;
  width: 30px;
  height: 20px;
  position: relative;
  z-index: 1001;
}

.mobile-toggle span {
  display: block;
  width: 100%;
  height: 2px;
  background-color: var(--text-primary);
  position: absolute;
  transition: all var(--transition-fast);
}

.mobile-toggle span:nth-child(1) { top: 0; }
.mobile-toggle span:nth-child(2) { top: 9px; }
.mobile-toggle span:nth-child(3) { top: 18px; }

.mobile-toggle.active span:nth-child(1) { transform: rotate(45deg); top: 9px; }
.mobile-toggle.active span:nth-child(2) { opacity: 0; }
.mobile-toggle.active span:nth-child(3) { transform: rotate(-45deg); top: 9px; }

/* Hero Carousel */
.hero-section {
  height: 100vh;
  min-height: 600px;
  position: relative;
  overflow: hidden;
}

.carousel-container {
  width: 100%;
  height: 100%;
  position: relative;
}

.carousel-track-wrapper {
  width: 100%;
  height: 100%;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  width: 100%;
  height: 100%;
  transition: transform var(--transition-slow);
}

.carousel-slide {
  min-width: 100%;
  height: 100%;
  position: relative;
  display: flex;
  align-items: center;
  padding: 0 var(--spacing-xl);
}

.slide-image {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-size: cover;
  background-position: center;
  z-index: -2;
}

.slide-image::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, rgba(10,10,10,0.9) 0%, rgba(10,10,10,0.4) 50%, rgba(10,10,10,0.1) 100%);
  z-index: -1;
}

.slide-content {
  max-width: 800px;
  opacity: 0;
  transform: translateY(20px);
  transition: all var(--transition-slow);
  transition-delay: 0.2s;
}

.carousel-slide.current-slide .slide-content {
  opacity: 1;
  transform: translateY(0);
}

.slide-label {
  display: inline-block;
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--accent-primary);
  margin-bottom: var(--spacing-sm);
  font-weight: 600;
}

.slide-title {
  margin-bottom: var(--spacing-md);
}

.slide-desc {
  font-size: clamp(1.125rem, 2vw, 1.5rem);
  color: var(--text-primary);
  margin-bottom: var(--spacing-lg);
  max-width: 600px;
}

.carousel-nav {
  position: absolute;
  bottom: var(--spacing-lg);
  left: var(--spacing-xl);
  display: flex;
  align-items: center;
  gap: var(--spacing-md);
  z-index: 10;
}

.carousel-btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
  color: var(--text-primary);
}

.carousel-btn:hover {
  background-color: var(--text-primary);
  color: var(--bg-color);
}

.carousel-btn svg {
  width: 24px;
  height: 24px;
}

.carousel-dots {
  display: flex;
  gap: 12px;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background-color: rgba(255,255,255,0.3);
  transition: all var(--transition-fast);
}

.carousel-dot.current-dot {
  background-color: var(--text-primary);
  transform: scale(1.2);
}

/* Sections Global */
section {
  padding: var(--spacing-xl) 0;
}

.section-header {
  margin-bottom: var(--spacing-lg);
}

.section-subtitle {
  font-size: 1.25rem;
  max-width: 700px;
}

/* Team Section */
.region-tabs {
  display: flex;
  gap: 1rem;
  margin-bottom: var(--spacing-lg);
  border-bottom: 1px solid var(--border-color);
  overflow-x: auto;
  scrollbar-width: none;
}

.region-tabs::-webkit-scrollbar {
  display: none;
}

.region-tab {
  padding: 1rem 0;
  font-size: 1.125rem;
  font-weight: 500;
  color: var(--text-secondary);
  position: relative;
  white-space: nowrap;
}

.region-tab::after {
  content: '';
  position: absolute;
  bottom: -1px;
  left: 0;
  width: 100%;
  height: 2px;
  background-color: transparent;
  transition: background-color var(--transition-fast);
}

.region-tab.active {
  color: var(--text-primary);
}

.region-tab.active::after {
  background-color: var(--accent-primary);
}

.team-carousel-container {
  position: relative;
}

.team-region {
  display: none;
  animation: fadeIn 0.5s ease forwards;
}

.team-region.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.team-grid {
  display: flex;
  gap: var(--spacing-md);
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  padding-bottom: var(--spacing-md);
  scrollbar-width: thin;
  scrollbar-color: var(--border-color) transparent;
}

.team-grid::-webkit-scrollbar {
  height: 6px;
}

.team-grid::-webkit-scrollbar-thumb {
  background-color: var(--border-color);
  border-radius: 3px;
}

.team-card {
  flex: 0 0 calc(50% - var(--spacing-md));
  min-width: 300px;
  background-color: var(--surface-color);
  border-radius: var(--radius-lg);
  overflow: hidden;
  scroll-snap-align: start;
}

.team-photo {
  height: 300px;
  background-size: cover;
  background-position: center;
}

.team-info {
  padding: var(--spacing-md);
}

.team-role {
  display: block;
  color: var(--accent-secondary);
  font-size: 0.875rem;
  margin-bottom: var(--spacing-sm);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.team-quote {
  font-size: 1rem;
  font-style: italic;
  margin-bottom: var(--spacing-md);
  color: var(--text-secondary);
  line-height: 1.6;
}

.team-cta {
  font-weight: 500;
  display: inline-flex;
  align-items: center;
}

.team-cta::after {
  content: '→';
  margin-left: 0.5rem;
  transition: transform var(--transition-fast);
}

.team-cta:hover::after {
  transform: translateX(4px);
}

/* Work Showcase */
.work-carousel-wrapper {
  overflow: hidden;
  margin: 0 calc(var(--spacing-md) * -1);
  padding: 0 var(--spacing-md);
}

.work-carousel {
  display: flex;
  gap: var(--spacing-lg);
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  padding-bottom: var(--spacing-lg);
  scrollbar-width: none;
}

.work-carousel::-webkit-scrollbar {
  display: none;
}

.work-card {
  flex: 0 0 calc(60vw);
  min-width: 300px;
  max-width: 800px;
  scroll-snap-align: center;
}

.work-image {
  width: 100%;
  aspect-ratio: 16/9;
  background-size: cover;
  background-position: center;
  border-radius: var(--radius-lg);
  margin-bottom: var(--spacing-md);
  transition: transform var(--transition-slow);
}

.work-card:hover .work-image {
  transform: scale(1.02);
}

.work-content h3 {
  color: var(--accent-primary);
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--spacing-xs);
}

.work-content h4 {
  font-size: 1.5rem;
  color: var(--text-primary);
  margin-bottom: var(--spacing-sm);
}

.work-quote {
  font-size: 1rem;
  font-style: italic;
  border-left: 2px solid var(--accent-secondary);
  padding-left: 1rem;
  margin-top: 1rem;
}

/* CTA Banner */
.cta-banner {
  background-color: var(--accent-primary);
  color: var(--bg-color);
  text-align: center;
  padding: var(--spacing-xl) 0;
}

.cta-inner p {
  color: rgba(0,0,0,0.8);
  font-size: 1.25rem;
  margin: 0 auto var(--spacing-md);
  max-width: 600px;
}

.cta-banner .btn-primary {
  background-color: var(--bg-color);
  color: var(--text-primary);
}

.cta-banner .btn-primary:hover {
  background-color: var(--text-primary);
  color: var(--bg-color);
}

/* How We Work */
.how-we-work {
  text-align: center;
}

.hww-content {
  max-width: 800px;
  margin: 0 auto;
}

.hww-content p {
  font-size: 1.5rem;
  margin-bottom: var(--spacing-md);
}

/* Latest Insights */
.insights-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: var(--spacing-md);
}

.insight-card {
  background-color: var(--surface-color);
  padding: var(--spacing-md);
  border-radius: var(--radius-lg);
  display: flex;
  flex-direction: column;
  transition: transform var(--transition-fast), background-color var(--transition-fast);
}

.insight-card:hover {
  transform: translateY(-5px);
  background-color: var(--surface-hover);
}

.insight-featured {
  grid-column: 1 / -1;
  background-color: var(--accent-secondary);
  color: var(--bg-color);
}

.insight-featured .insight-title,
.insight-featured .insight-link,
.insight-featured .insight-type {
  color: var(--bg-color);
}

.insight-type {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--accent-primary);
  margin-bottom: var(--spacing-sm);
  font-weight: 600;
}

.insight-title {
  font-size: 1.25rem;
  margin-bottom: var(--spacing-md);
  flex-grow: 1;
}

.insight-link {
  display: inline-flex;
  align-items: center;
  font-weight: 600;
  text-transform: uppercase;
  font-size: 0.875rem;
}

.insight-link svg {
  width: 16px;
  height: 16px;
  margin-left: 0.5rem;
  transition: transform var(--transition-fast);
}

.insight-card:hover .insight-link svg {
  transform: translateX(4px) translateY(-4px);
}

/* Principles */
.principles-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--spacing-lg);
}

.principle-item {
  border-top: 1px solid var(--border-color);
  padding-top: var(--spacing-md);
}

.principle-num {
  font-size: 3rem;
  font-weight: 700;
  color: var(--border-color);
  display: block;
  margin-bottom: var(--spacing-sm);
}

/* Footer */
.site-footer {
  border-top: 1px solid var(--border-color);
  padding-top: var(--spacing-xl);
  padding-bottom: var(--spacing-md);
}

.footer-top {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-lg);
  margin-bottom: var(--spacing-xl);
}

.footer-cta h3 {
  font-size: 2rem;
}

.footer-cta p {
  margin-bottom: var(--spacing-md);
}

.footer-links-area {
  margin-bottom: var(--spacing-lg);
}

.footer-nav {
  display: flex;
  gap: var(--spacing-md);
  flex-wrap: wrap;
}

.footer-nav a {
  font-size: 1.125rem;
  font-weight: 500;
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--spacing-sm);
  border-top: 1px solid var(--border-color);
  padding-top: var(--spacing-md);
  font-size: 0.875rem;
  color: var(--text-secondary);
}

.legal-links {
  display: flex;
  gap: 1rem;
}

.legal-links a, .legal-links button {
  color: var(--text-secondary);
}

.legal-links a:hover, .legal-links button:hover {
  color: var(--text-primary);
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  width: 100%;
  background-color: var(--surface-color);
  padding: var(--spacing-md);
  z-index: 9999;
  border-top: 1px solid var(--border-color);
  transform: translateY(100%);
  transition: transform var(--transition-normal);
}

.cookie-banner.show {
  transform: translateY(0);
}

.cookie-content {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--spacing-md);
  flex-wrap: wrap;
}

.cookie-content p {
  margin: 0;
  flex: 1;
  min-width: 280px;
}

.cookie-actions {
  display: flex;
  gap: var(--spacing-sm);
}

/* Responsive */
@media (max-width: 992px) {
  .carousel-slide { padding: 0 var(--spacing-md); }
  .carousel-nav { left: var(--spacing-md); bottom: var(--spacing-md); }
  .team-card { flex: 0 0 calc(100% - var(--spacing-md)); }
  .work-card { flex: 0 0 85vw; }
  .principles-grid { grid-template-columns: 1fr; }
  .footer-top { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .mobile-toggle { display: block; }
  .main-nav {
    position: fixed;
    top: 5rem;
    left: 0;
    width: 100%;
    height: calc(100vh - 5rem);
    background-color: var(--bg-color);
    padding: var(--spacing-md);
    flex-direction: column;
    align-items: flex-start;
    transform: translateX(100%);
    transition: transform var(--transition-normal);
    overflow-y: auto;
  }
  .main-nav.active { transform: translateX(0); }
  .nav-list {
    flex-direction: column;
    width: 100%;
    align-items: flex-start;
    gap: var(--spacing-md);
  }
  .nav-list a, .language-toggle { font-size: 1.25rem; }

  .language-dropdown {
    position: static;
    box-shadow: none;
    background: transparent;
    border: none;
    padding-left: 1rem;
    display: none;
    opacity: 1;
    visibility: visible;
    transform: none;
  }
  .language-dropdown.show { display: block; }

  .hww-content p { font-size: 1.25rem; }
  .footer-bottom { flex-direction: column; text-align: center; }
}

document.addEventListener('DOMContentLoaded', () => {
  // Mobile Menu Toggle
  const mobileToggle = document.querySelector('.mobile-toggle');
  const mainNav = document.querySelector('.main-nav');

  if (mobileToggle && mainNav) {
    mobileToggle.addEventListener('click', () => {
      const isExpanded = mobileToggle.getAttribute('aria-expanded') === 'true';
      mobileToggle.setAttribute('aria-expanded', !isExpanded);
      mobileToggle.classList.toggle('active');
      mainNav.classList.toggle('active');
    });
  }

  // Language Dropdown Toggle
  const langToggle = document.querySelector('.language-toggle');
  const langDropdown = document.querySelector('.language-dropdown');

  if (langToggle && langDropdown) {
    langToggle.addEventListener('click', (e) => {
      e.stopPropagation();
      const isExpanded = langToggle.getAttribute('aria-expanded') === 'true';
      langToggle.setAttribute('aria-expanded', !isExpanded);
      langDropdown.classList.toggle('show');
    });

    document.addEventListener('click', (e) => {
      if (!langToggle.contains(e.target) && !langDropdown.contains(e.target)) {
        langToggle.setAttribute('aria-expanded', 'false');
        langDropdown.classList.remove('show');
      }
    });
  }

  // Header Scroll Effect
  const header = document.querySelector('.site-header');
  window.addEventListener('scroll', () => {
    if (window.scrollY > 50) {
      header.style.padding = '0.5rem 0';
      header.style.background = 'rgba(10, 10, 10, 0.95)';
    } else {
      header.style.padding = '0';
      header.style.background = 'rgba(12, 12, 14, 0.8)';
    }
  });

  // Hero Carousel
  const track = document.querySelector('.carousel-track');
  const slides = Array.from(track.children);
  const nextButton = document.querySelector('.next-btn');
  const prevButton = document.querySelector('.prev-btn');
  const dotsNav = document.querySelector('.carousel-dots');
  const dots = Array.from(dotsNav.children);

  let currentSlideIndex = 0;
  let autoplayInterval;

  const updateCarousel = (index) => {
    track.style.transform = 'translateX(-' + index * 100 + '%)';

    slides.forEach(slide => slide.classList.remove('current-slide'));
    slides[index].classList.add('current-slide');

    dots.forEach(dot => dot.classList.remove('current-dot'));
    dots[index].classList.add('current-dot');
  };

  const nextSlide = () => {
    currentSlideIndex = (currentSlideIndex + 1) % slides.length;
    updateCarousel(currentSlideIndex);
  };

  const prevSlide = () => {
    currentSlideIndex = (currentSlideIndex - 1 + slides.length) % slides.length;
    updateCarousel(currentSlideIndex);
  };

  if (nextButton && prevButton) {
    nextButton.addEventListener('click', () => {
      nextSlide();
      resetAutoplay();
    });

    prevButton.addEventListener('click', () => {
      prevSlide();
      resetAutoplay();
    });
  }

  dots.forEach((dot, index) => {
    dot.addEventListener('click', () => {
      currentSlideIndex = index;
      updateCarousel(currentSlideIndex);
      resetAutoplay();
    });
  });

  const startAutoplay = () => {
    autoplayInterval = setInterval(nextSlide, 5000);
  };

  const resetAutoplay = () => {
    clearInterval(autoplayInterval);
    startAutoplay();
  };

  startAutoplay();

  // Team Region Tabs
  const regionTabs = document.querySelectorAll('.region-tab');
  const teamRegions = document.querySelectorAll('.team-region');

  regionTabs.forEach(tab => {
    tab.addEventListener('click', () => {
      // Remove active classes
      regionTabs.forEach(t => t.classList.remove('active'));
      teamRegions.forEach(r => r.classList.remove('active'));

      // Add active class to clicked tab and corresponding region
      tab.classList.add('active');
      const regionId = tab.getAttribute('data-region');
      document.getElementById('region-' + regionId).classList.add('active');
    });
  });

  // Cookie Banner
  const cookieBanner = document.getElementById('cookie-banner');
  const acceptBtn = document.getElementById('accept-cookies');
  const declineBtn = document.getElementById('decline-cookies');

  if (cookieBanner) {
    // Show banner after short delay if not previously accepted/declined
    if (!localStorage.getItem('cookieConsent')) {
      setTimeout(() => {
        cookieBanner.classList.add('show');
      }, 1000);
    }

    const closeBanner = () => {
      cookieBanner.classList.remove('show');
    };

    if (acceptBtn) {
      acceptBtn.addEventListener('click', () => {
        localStorage.setItem('cookieConsent', 'accepted');
        closeBanner();
      });
    }

    if (declineBtn) {
      declineBtn.addEventListener('click', () => {
        localStorage.setItem('cookieConsent', 'declined');
        closeBanner();
      });
    }
  }
});
